import {fishBiomass} from './fish-state.js';
/** Fictional oxygen budget. Every admitted/used/released mg is accounted. @param {import('./fish-state.js').FishPond} pond @param {number} tick @param {import('./engine.js').Weather} weather */
export function stepFishOxygen(pond,tick,weather){const day=tick%24>=6&&tick%24<18,saturation=pond.volumeL*(weather==='hot'?7:8);if(pond.oxygenMg>saturation){pond.balance.oxygenOutMg+=pond.oxygenMg-saturation;pond.oxygenMg=saturation;}const demand=Math.ceil(fishBiomass(pond)*(weather==='hot'?14:10)/100)+Math.ceil(pond.sludgeG/5)+Math.floor(pond.pendingFeedG/20),used=Math.min(pond.oxygenMg,demand);pond.oxygenMg-=used;pond.balance.oxygenUsedMg+=used;const incoming=Math.max(0,Math.floor((saturation-pond.oxygenMg)*(day?20:10)/1000));pond.oxygenMg+=incoming;pond.balance.oxygenInMg+=incoming;return {usedMg:used,surfaceMg:incoming};}
